TypeScript automatic fallback example:

import { StreamingClient } from '@redwood/sdk'

const client = new StreamingClient({ degradationMode: 'partial', maxRetries: 3 })

for await (const chunk of client.streamGenerate(prompt)) {
  if (chunk.partial) {
    console.warn('stream degraded; resume token:', chunk.resumeToken)
  }
  process.stdout.write(chunk.text)
}

Go resume example:

c, err := sdk.NewStreamingClient(sdk.WithDegradationMode(sdk.DegradePartial))
if err != nil { log.Fatal(err) }
stream, _ := c.StreamGenerate(ctx, req)
for {
  chunk, err := stream.Recv()
  if err == io.EOF { break }
  if err != nil {
    if errors.Is(err, sdk.ErrRetryableTransient) {
      // SDK handled retries; inspect resume token
      if rt := stream.ResumeToken(); rt != "" {
        log.Printf("partial result, resume token=%s", rt)
      }
    }
    break
  }
  fmt.Print(chunk.Text)
}
